<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">    PRODUCT_NAME </span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">&quot;My Plugin&quot;</span></span>
